BEGIN TRANSACTION READ ONLY;
SELECT p.prosecdef AS security_definer,p.proconfig AS settings,md5(regexp_replace(p.prosrc,'\s+','','g')) AS body_md5,has_function_privilege('anon',p.oid,'EXECUTE') AS anon_execute,has_function_privilege('authenticated',p.oid,'EXECUTE') AS authenticated_execute,has_function_privilege('service_role',p.oid,'EXECUTE') AS service_role_execute,(SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version='20261101020000') AS migration_rows,(SELECT count(*) FROM auth.users WHERE email LIKE '%@bedos-setup-test.invalid') AS fixture_users,(SELECT count(*) FROM pg_trigger WHERE tgname IN ('bedos_setup_test_audit','bedos_setup_test_profile')) AS test_triggers,(SELECT jsonb_object_agg(p2.proname,md5(regexp_replace(p2.prosrc,'\s+','','g'))) FROM pg_proc p2 JOIN pg_namespace n2 ON n2.oid=p2.pronamespace WHERE n2.nspname='public' AND p2.proname IN ('bedos_authorize_staff_invitation','bedos_prepare_staff_invitation_retry','bedos_finish_staff_invitation_retry','bedos_record_staff_invitation_password_baseline','bedos_activate_staff_invitation','bedos_revoke_staff_invitation')) AS dependency_hashes,(SELECT jsonb_agg(jsonb_build_object('role',grantee,'privilege',privilege_type) ORDER BY grantee,privilege_type) FROM information_schema.table_privileges WHERE table_schema='public' AND table_name='audit_logs' AND grantee IN ('PUBLIC','anon','authenticated','service_role')) AS audit_grants FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='bedos_setup_staff_invitation';
COMMIT;
